-- Rucksack / the Guide (10 Nov): what every part does, shown on the Guide page of the
-- window. Each page's "?" button opens the Guide at its own section. Plain text, easy to edit.
local _, ns = ...

local Y = "|cffffd100" -- an option's name
local G = "|cff999999" -- a side note
local R = "|r"

ns.GUIDE = {
  { key = "home", title = "|cffc8a165Ruck|r|cffffd100sack|r", text = table.concat({
    "Rucksack takes care of the two chores every adventurer repeats all day: eating and drinking, and full bags.",
    "",
    Y .. "Rations" .. R .. " picks the right food and water for you and eats and drinks with one click. No more searching your bags after every fight or eating the wrong stack.",
    Y .. "Clean-up" .. R .. " keeps a few bag slots free for you, always. When space runs low, the cheapest junk goes first (or gets sold at the next vendor), and quest items stay.",
    "",
    Y .. "Home" .. R .. " (the page that opens with /ruck) shows everything at a glance:",
    "·  " .. Y .. "Bag space" .. R .. ": free slots. The bar turns yellow, then red, as your bags fill up.",
    "·  " .. Y .. "Rations card" .. R .. ": your next food and water, how many you have, and the rules you picked.",
    "·  " .. Y .. "Clean-up card" .. R .. ": how many items can go when your bags fill up and which goes first, what a vendor would pay you right now, the gold you've made from selling, and how many items were deleted. " .. Y .. "Delete next" .. R .. " deletes the next waiting item now.",
    "·  " .. Y .. "Right now" .. R .. ": what Rucksack is doing on its own, like keeping items your quests need.",
    "Click a card to open that tool. The sidebar on the left switches pages; every tool in the list is turned on (Settings > Modules); its page has a \"Show button\" box for its button on screen.",
  }, "\n") },

  { key = "eat", title = "|cff66dd66Rations|r  ·  eat and drink with one click", text = table.concat({
    Y .. "The eat button" .. R .. ": a button on your screen with your food on the left and your water on the right, with how many you have. Click it to eat and drink at once. Shift-drag to move it. It turns grey in combat, because the game doesn't let you eat or drink in a fight.",
    Y .. "Macros" .. R .. ": Rucksack makes " .. Y .. "EatDrink" .. R .. ", " .. Y .. "Eat" .. R .. " and " .. Y .. "Drink" .. R .. " for all your characters (Esc > Macros > General). Drag them onto your bars; they always use your best food and water.",
    Y .. "Macros" .. R .. ": three macros shared by all your characters (/macro, General tab), kept up to date with the food and water of whoever you're playing: " .. Y .. "EatDrink" .. R .. " (like the button), " .. Y .. "Eat" .. R .. " (food only) and " .. Y .. "Drink" .. R .. " (water only). On the Rations page, drag one straight onto your bars, or click " .. Y .. "Create macros" .. R .. " to make any that are missing.",
    Y .. "Eat button" .. R .. " (pick one of the four): " .. Y .. "Food and water" .. R .. " (one click eats and drinks), " .. Y .. "Food only" .. R .. ", " .. Y .. "Water only" .. R .. ", or " .. Y .. "Separate" .. R .. " (two buttons side by side: click the food to eat, the water to drink).",
    "",
    Y .. "Use first" .. R .. " (which food and water it picks):",
    "·  " .. Y .. "Strongest first" .. R .. ": the one that restores the most.",
    "·  " .. Y .. "Conjured first" .. R .. ": mage food and water first.",
    "·  " .. Y .. "Save conjured" .. R .. ": everything else first; conjured food and water are kept for later.",
    "·  " .. Y .. "Random" .. R .. ": a different one each time.",
    Y .. "Food level" .. R .. ":",
    "·  " .. Y .. "Any level" .. R .. ": all food and water you're able to eat.",
    "·  " .. Y .. "Only my level" .. R .. ": only the two newest levels you can eat. Older food is used only when nothing else is left.",
    "·  " .. Y .. "Use up old food" .. R .. ": the lowest level first, so old food doesn't pile up. " .. G .. "(Not with Random.)" .. R,
    Y .. "Delete below level" .. R .. ": " .. Y .. "Off" .. R .. ", " .. Y .. "Auto" .. R .. " (food and water too weak for your level), or a level from 5 to 55. Food and water below it are deleted by Clean-up when your bags are nearly full. " .. G .. "(Clean-up must be on.)" .. R,
    Y .. "Delete all water as soon as I get it" .. R .. ": for characters with no mana. Set for each character, and on by default for warriors and rogues. Clean-up deletes the water on your next key press.",
    "",
    Y .. "The list" .. R .. ": all food and water in your bags. Click one to set " .. Y .. "Use this first" .. R .. " (always picked before the rest, never deleted) or " .. Y .. "Never use this" .. R .. ".",
    Y .. "Eat buff food when the buff is missing" .. R .. ": food that gives a buff (Well Fed) is normally kept. Ticked, the eat button uses it first whenever you're not Well Fed, then goes back to plain food. The " .. Y .. "Buff" .. R .. " tick on top of the eat button (and on the Pocket's food) switches it on or off too.",
    Y .. "Buff" .. R .. " on top of the eat button: green when buff food is on, red when it's off; click it to switch. " .. Y .. "Remind me when I'm not Well Fed" .. R .. " (this character): " .. Y .. "Alert" .. R .. " (big text; untick under it to turn buff food off) or " .. Y .. "Off" .. R .. ". Never in a fight, while eating, or without buff food in your bags.",
    Y .. "Alert me while I eat for the buff" .. R .. ": while you eat buff food, the middle of the screen says \"don't move\" with a 10-second countdown, then \"Well Fed! You can move now.\" " .. Y .. "Move the alert" .. R .. " lets you drag it anywhere.",
    G .. "Never eaten: buff food (unless the box above is ticked), food above your level, and anything on your Clean-up list." .. R,
  }, "\n") },

  { key = "del", title = "|cffff5555Clean-up|r  ·  delete what you don't need", text = table.concat({
    "Clean-up is like a little bag helper. You pick how many free slots you always want to keep, say 4. As soon as you drop below that, it throws out your " .. Y .. "cheapest junk first" .. R .. ", the stuff worth the least, until you're back to 4 free slots. No more \"Inventory is full\" in the middle of a dungeon.",
    "Grey trash goes by itself. Anything else only goes if you told it to: click " .. Y .. "Always" .. R .. " when you delete something once, and Clean-up remembers it. Passing a vendor? It " .. Y .. "sells" .. R .. " the junk for gold instead. And it never touches what your quests still need: if a quest wants 8 wolf pelts, it keeps 8.",
    "",
    Y .. "Destroying an item" .. R .. ": drag it out of your bag and Rucksack asks: Delete it? If it's needed for something (a quest, a Darkmoon turn-in, a rare or better item...) the box says what. Delete or Cancel. Your lists and the windows beside the bag stay as they are. To sell or delete it later instead, drop it on one of those windows. Conjured food and water are still deleted without asking.",
    Y .. "Delete items worth up to" .. R .. ": the slider under \"Always sell / delete\", 10 silver to 5 gold (all the way right: no limit). When your bags are nearly full, Rucksack only throws away a stack worth up to this much; a stack worth more is kept and sold at the next vendor. Selling has no limit. It's the same setting as the delete limit on the Clean-up page.",
    Y .. "Why a key press" .. R .. ": the game only lets an addon delete an item during a click or a key press. So Clean-up deletes one waiting item each time you press a key or click the trash button. Never in combat.",
    "",
    Y .. "Delete on any key press" .. R .. ": on, any key you press out of combat deletes the next waiting item. Off, only the trash button or the RuckDelete macro does.",
    Y .. "Chat message when deleting" .. R .. ": prints a line in chat for each item deleted.",
    Y .. "Always show the trash button" .. R .. ": the trash button normally shows only when something is waiting. Click it to delete the next item; Shift-drag to move it.",
    Y .. "Keep empty slots" .. R .. ": how many free bag slots Clean-up keeps for you. Drop below it and the cheapest stack goes first.",
    Y .. "Goes by itself" .. R .. ": grey items; white weapons and armour your class can't wear, or that are worse than what you wear in that slot (less armour; weapons: less damage per second); and soulbound gear of any quality your class can't use. Better gear, gear for an empty slot, and " .. Y .. "profession tools" .. R .. " (Skinning Knife, Mining Pick, fishing poles, enchanting rods...) stay, unless you put one in a box or on Sell yourself. Everything else goes only once you delete it yourself with Always. All of it is sold at a vendor, or deleted when your bags are nearly full, cheapest first.",
    Y .. "Don't delete anything worth more than" .. R .. ": a stack worth more than this (1g to start; a slider from 10s to 5g in 10s steps, - and + or the mouse wheel step 10s, or tick No limit) isn't deleted. Clean-up stops and tells you; click the trash button to choose " .. Y .. "Delete it" .. R .. ", " .. Y .. "Keep it" .. R .. " or " .. Y .. "Not now" .. R .. ". It goes on by itself once you free up a bag slot. Selling isn't limited.",
    Y .. "RuckDelete macro" .. R .. ": put it on your bars. It does the same as clicking the trash button: throws the first item away now, full bags or not, and shows that item's icon and tooltip.",
    Y .. "Drop an item here" .. R .. ": drag an item onto the box to put it on your list without deleting it. With Bags on, the box is gone: drop the item on " .. Y .. "Always sell / delete" .. R .. " or " .. Y .. "Sell / delete once" .. R .. " on the right of your bag instead.",
    "",
    Y .. "Each item" .. R .. " (click it in the list): " .. Y .. "When my bags are nearly full" .. R .. " or " .. Y .. "As soon as I get it" .. R .. ", and " .. Y .. "Stop deleting it" .. R .. ". An item caught by a rule (junk, or a Rations rule) has a " .. Y .. "Keep" .. R .. " button in the list.",
    Y .. "Quest items" .. R .. ": Clean-up keeps exactly the amount your current quests still need and deletes only the extra. Items that start a quest are kept.",
    Y .. "The list" .. R .. ": search by name, then pick " .. Y .. "Everything" .. R .. ", " .. Y .. "My list" .. R .. " (the white and better items you chose; " .. Y .. "Remove" .. R .. " takes one off), " .. Y .. "In my bags" .. R .. " or " .. Y .. "Deleted" .. R .. " (the last 100 items deleted: how many, when and why), and filter by quality.",
  }, "\n") },

  { key = "sell", title = "|cffffd100Selling|r  ·  gold instead of deleting", text = table.concat({
    "When you open a vendor, Rucksack sells for you, a few items at a time. A line in chat says what it sold and for how much.",
    Y .. "At a vendor: sell my Clean-up items for gold" .. R .. " " .. G .. "(on by default)" .. R .. ": everything Clean-up would delete is sold instead, if you reach a vendor before your bags fill up. Deleting pays nothing; selling pays gold, and you can buy it back from the vendor if you made a mistake.",
    Y .. "Sell grey items" .. R .. ": every grey item with a price is sold.",
    Y .. "Sell soulbound gear I can't use" .. R .. ": soulbound weapons your class can never use (by WoW Forever's weapon trainers), and shields and relics that aren't for your class. Tick " .. Y .. "Cloth, Leather, Mail or Plate" .. R .. " to also sell soulbound armor of types this character never wears. Only ever sold, never deleted. Up to blue; epics, cloaks and unbound gear are kept.",
    G .. "Never sold: amounts your quests need, items set to Keep, items with no vendor price, and blue or better unless you put them on your list yourself." .. R,
    Y .. "Hold Shift" .. R .. " while opening the vendor to sell nothing that time. " .. G .. "(The vendor can buy back only your last 12 items.)" .. R,
    "Home shows what a vendor would pay right now and the gold you've made so far.",
  }, "\n") },

  { key = "pocket", title = "|cffffd100The Pocket|r  ·  a small window that stays on screen", text = table.concat({
    "What it shows: " .. Y .. "Bags" .. R .. " (free slots), " .. Y .. "Vendor" .. R .. " (what a vendor would pay right now; hover it for the list), " .. Y .. "Food" .. R .. ", " .. Y .. "Water" .. R .. ", " .. Y .. "Next to delete" .. R .. " (what Clean-up throws out next, and how many are waiting), your Darkmoon " .. Y .. "Prize" .. R .. " (or tickets) and your " .. Y .. "Scrolls" .. R .. ".",
    Y .. "Four styles" .. R .. " (Settings): " .. Y .. "Rows" .. R .. " (one short line each), " .. Y .. "Tiles" .. R .. " (big numbers in a grid, bag space on top, the prize as a strip), " .. Y .. "Strip" .. R .. " (just icons and numbers in one bar) and " .. Y .. "Ledger" .. R .. " (text only).",
    "A red edge: something is waiting to be deleted. Green: your prize or tickets are ready, or scrolls you can read.",
    "Click an entry to open its page. Shift-click " .. Y .. "Next to delete" .. R .. " to delete it now. " .. Y .. "Right-click" .. R .. " anywhere on it: Settings. Drag it to move it.",
    "Show or hide it: the box on Home or Settings, or right-click the minimap button.",
    "On Settings: " .. Y .. "Lock it in place" .. R .. ", " .. Y .. "Hide it in combat" .. R .. ", " .. Y .. "Size" .. R .. ", " .. Y .. "Style" .. R .. ", and which " .. Y .. "Lines" .. R .. " to show.",
  }, "\n") },

  { key = "faire", title = "|cffb48cffDarkmoon Faire|r  ·  tickets, turn-ins and prizes", text = table.concat({
    "Once a month the Darkmoon Faire comes to Elwynn Forest or Mulgore. Four of its people trade " .. Y .. "prize tickets" .. R .. " for things you bring them: animal parts, and blacksmithing, engineering and leatherworking items. Gelvas Grimegate swaps the tickets for prizes, like a 14-slot bag for 50.",
    "",
    Y .. "Turn-ins" .. R .. ": every ticket quest, how many items it wants, how many you have (the bank too, once you've opened it) and the tickets it gives. " .. Y .. "Ready" .. R .. " means you can hand it in now. " .. Y .. "Closed" .. R .. " means your Faire reputation is past that quest's limit: bring higher ones.",
    Y .. "Where to get it" .. R .. ": click a turn-in. Animal parts list good places to farm, closest to your level first. Click one to " .. Y .. "pin it on your map" .. R .. " (shift-click pins them all). Crafted items show their profession, and their materials once you open that profession's window.",
    Y .. "Plan" .. R .. ": pick a prize with < and >, tick the turn-ins you want to use, and Rucksack works out how many hand-ins that is and what you still have to get: the items, or the materials to make them (one step deep: bars, not ore). - and + set a number yourself. " .. Y .. "Left" .. R .. " is how many more hand-ins your reputation allows; if an NPC stops offering one, it shows as closed for the day. Click an item to see where it comes from. With " .. Y .. "Show button" .. R .. " ticked (top of the page), the prize card on your screen shows the plan as a table: what you have of each, the tickets, and the hand-ins left. It also lists turn-in items you just happen to have.",
    Y .. "Prizes" .. R .. ": click a prize to " .. Y .. "track" .. R .. " it. The Pocket's Tickets line and Home show it as 37 / 50. Want it on screen too? Turn on " .. Y .. "Button on screen" .. R .. " (Faire & Sayge tab): a little card that fills up and glows gold when you have enough.",
    Y .. "Decks" .. R .. ": which Darkmoon cards you have, Ace to Eight, for all four decks.",
    Y .. "Faire & Sayge" .. R .. ": when and where the Faire is, Sayge's answers (1 then 1 = +10% damage) and the settings.",
    "",
    Y .. "Quick turn-ins" .. R .. ": talk to Yebb, Kerri, Rinling or Chronos and the quests you have items for are handed in for you. Hold Shift to do it yourself. Prizes are never bought for you.",
    Y .. "Keep Darkmoon turn-in items" .. R .. ": Clean-up never deletes or sells them, even the grey ones like Small Furry Paws.",
    Y .. "Tooltips" .. R .. ": turn-in items say who wants them and how many tickets they give.",
  }, "\n") },

  { key = "bags", title = "|cffd9a35aBags|r  ·  one bag window", text = table.concat({
    "Rucksack is a bag addon: the " .. Y .. "Bags" .. R .. " card in Settings > Modules is on to start, with selling, deleting and the bank built in. Turn off other bag addons (Bagnon, Baganator...) while it's on. " .. Y .. "B" .. R .. ", the bag buttons, vendors and mail open Rucksack's bag. Items work as always: click, drag, split, use. Its settings are on the " .. Y .. "Bags" .. R .. " page in the list on the left (or click " .. Y .. "Opt." .. R .. " in the bag).",
    "",
    Y .. "Look" .. R .. ": " .. Y .. "Groups" .. R .. " puts items in labelled groups (Weapons, Armour, Consumables (food, water and potions), Trade goods, Quest, Everything else and your own), side by side; a group that doesn't fit goes to the next row. Pick " .. Y .. "Rows" .. R .. " on the Bags page for each group on its own row. " .. Y .. "One bag" .. R .. " has no groups: your items where they really are, nothing moves by itself (reagents neither). The reagent bag's slots are green. Click " .. Y .. "Tidy" .. R .. " to sort them once (the game's own sort); after that they stay where they are again.",
    Y .. "The header" .. R .. ": search, then icons (hover each for what it does): your characters, the bank, Tidy, Stacks (Merged or Separate), Look (Groups or One bag), the gear (settings).",
    Y .. "Stacks" .. R .. ": " .. Y .. "Merged" .. R .. " shows all of one item as one icon (80 ore as 80); " .. Y .. "Separate" .. R .. " shows the real stacks.",
    Y .. "Search" .. R .. ": type part of a name and everything else goes dark.",
    Y .. "The tool row" .. R .. " under Rucksack's icon: " .. Y .. "Haul" .. R .. " (click: open or close it; right-click: start or pause a run; gold while a run is on), " .. Y .. "Track" .. R .. " (opens another Track bar), " .. Y .. "Restock" .. R .. " and " .. Y .. "Hidden" .. R .. ". " .. Y .. "Boxes" .. R .. " (which corner the boxes sit in) is in the header, left of Your characters. The bags row opens between the header and this row.",
    Y .. "Show or hide the boxes" .. R .. ": three small buttons sit on the bag's edge, beside the boxes: Always sell / delete, Sell / delete once (the one with a 1) and Send to bank. Click one to hide that box or show it again (all shown to start). A hidden box's items go back in your bag (the sell / delete ones in Junk at the bottom), and Rucksack still sells, deletes and banks them as before.",
    Y .. "Look" .. R .. " (in the header): each click goes to the next look: " .. Y .. "Rows" .. R .. " (each group on a line of its own), " .. Y .. "Packed" .. R .. " (groups side by side) and " .. Y .. "One bag" .. R .. " (no groups); right-click goes back.",
    Y .. "The bags row" .. R .. ": the arrow next to Rucksack in the bag's corner opens it (click again: it closes); Rucksack's icon itself opens the Bags settings. In it: your four bags and the reagent bag, each with its free slots; then New group, Delete group and the padlock. Hover one and only its slots stay bright. " .. Y .. "Drop a bag on a bag" .. R .. " to swap it, even when the old one is full: Rucksack moves its items into your other bags first (and the bank, if it's open). No room? It says how many slots are missing and offers to delete junk or use an empty bag slot. Click a bag to take it out: its items go into your other bags first, then the bag goes into a free slot (not in a fight).",
    Y .. "Empty slots" .. R .. ": every empty slot is shown at the end (drop an item on any); the reagent bag's empty slots are in Empty too, after the others, in green; special bags' empty slots are in their own groups. The free number at the bottom only counts slots any item can use.",
    Y .. "New" .. R .. ": what you just got sits in a New group at the front, with a gold frame, until you've pointed at it or closed the bag.",
    Y .. "Tidy" .. R .. ": puts half-full stacks of the same item together, which frees slots.",
    Y .. "Bag sounds" .. R .. ": the game's own sound when the bag opens and closes (a tick on the Bags page).",
    Y .. "Tags" .. R .. ": " .. Y .. "BoE" .. R .. " is gear that isn't bound yet (you can still sell or send it); " .. Y .. "open" .. R .. " is a lockbox, clam or other container to open.",
    Y .. "The boxes on the right" .. R .. ": three boxes next to your bag. Each shows the items in your bags that belong to it, and has a " .. Y .. "?" .. R .. " that says what it does. " .. Y .. "Always sell / delete" .. R .. ": every one of that item, also later; a vendor buys it, or it's thrown away when your bags fill up, cheapest first (the first to go has a red frame). Grey items and gear you can't use land there by themselves. " .. Y .. "Sell / delete once" .. R .. ": only the stack you dropped there. Next to the names of these two boxes are two ticks, " .. Y .. "sell" .. R .. " and " .. Y .. "delete" .. R .. ": untick one and Rucksack doesn't do that to what's in that box. " .. Y .. "Send to bank" .. R .. ": only the stacks you put there go into your bank when you open it, and Clean-up never sells or throws them away. " .. Y .. "Alt + left-click" .. R .. " an item in your bag sends that stack there (at the bank it goes straight in); " .. Y .. "Alt + right-click" .. R .. " an item in any of the three boxes takes it out: back in your bag, no longer sold, thrown away or sent to the bank. Under the first box's name is " .. Y .. "Delete items worth up to" .. R .. ": a stack worth more is never thrown away by itself, only sold at a vendor. While you wear a quiver or ammo pouch, a fourth window, " .. Y .. "Quiver" .. R .. ", shows it slot by slot with how many arrows you have, and arrows and bullets in your other bags move into it by itself (both can be turned off on the Bags page). " .. Y .. "Special bags" .. R .. " (herb, soul, mining, enchanting bags, the quiver...): their slots are tinted with a thin border in that bag's colour, each is its own group in the bag with how full it is (Soul bag 12/16): one tile per item with the total, or slot by slot (click its colour at the bottom of the Bags page to choose), and anything that fits one moves into it by itself when there's room, before the reagent bag (\"Sort into special bags\" on the Bags page). Pick each kind's colour at the bottom of the Bags page. \"Delete extra soul shards\" on the Bags page (on to start; greyed out without a soul bag) deletes a shard that lands outside your soul bag once the soul bag is full (never without a soul bag, never one a quest needs). The " .. Y .. "Boxes" .. R .. " button in the bags row (next to Restock) moves them to the next corner of the bag each click: top right, bottom right, bottom left, top left (right-click goes the other way). The same choice is on the Bags page.",
    Y .. "Putting an item in a box" .. R .. ": pick it up and drop it on the box. To take it out again, pick it up: a green slot shows up first in its box. Drop it there and it stays in your bags like before. That works with the padlock on too. Useful things ask first (a profession tool too). If your bank is full, what doesn't fit stays in your bags and chat says so; " .. Y .. "Put in bank now" .. R .. " in the box tries again.",
    Y .. "Putting an item in a group" .. R .. ": pick it up and every group gets an empty slot at its end with a green " .. Y .. "+" .. R .. "; the group under your mouse lights up. Drop the item on a slot and it goes in that group from now on, all its stacks, on all your characters. Dropping on a group's name works too.",
    Y .. "Changing your mind" .. R .. ": drop it on another group's slot to move it, or on its own group's slot again and it goes back where Rucksack puts it. " .. Y .. "Put items back" .. R .. " on the Bags page undoes them all. In a fight, drop on a group's name.",
    Y .. "Moving groups" .. R .. ": drag a group by its name: it lifts and follows the mouse, the others slide out of the way, and it settles where you let go. Every group moves, Empty too. The order is the same for all your characters; " .. Y .. "Reset order" .. R .. " on the Bags page puts it back. (In a fight: a gold line shows where it lands, and the new order shows after the fight.)",
    Y .. "Each character its own" .. R .. ": Restock, Hidden and the Always sell / delete and Keep lists belong to the character you play (each one started with the lists you had). Groups, their order and the settings are the same for all your characters.",
    Y .. "Your own groups" .. R .. ": the green " .. Y .. "+" .. R .. " in the bags row makes one (name it), or drop an item on it and the new group starts with that item. Your groups show even when empty. Right-click one's name to rename it, change its colour or delete it; or click the " .. Y .. "bin" .. R .. " next to the +, then a group's name (or drag a group onto it). Deleting a group sends its items back where Rucksack puts them.",
    Y .. "The padlock" .. R .. " (next to the bin) locks the groups: no moving, making or deleting groups by accident. Items still move: pick one up and drop it in another group, and it stays there. Click it again to unlock.",
    Y .. "Order inside a group" .. R .. ": best quality first, then by name, the bigger stack first. While the bag is open nothing changes places by itself; a new item goes to the end of its group. When you open the bag again (or click Tidy) each group is sorted afresh.",
    Y .. "The game's bag buttons" .. R .. " (the backpack and bag slots at the bottom right) are hidden while Bags is on: the bags row has the same slots. Untick " .. Y .. "Hide the game's bag buttons" .. R .. " on the Bags page to have them back (after a reload).",
    Y .. "The pin" .. R .. " (first on the left of the bags row) keeps the bag window where it is: while it's pinned, dragging the window does nothing. Click it again to move the window.",
    Y .. "Your bank and your other characters" .. R .. " open in a second window next to the bag. The bank icon at the top: your bank, as it was when you last opened it (at a banker it opens by itself, live: drag items between it and your bags). The people icon: your other characters (each one you've played with Bags on); the icon in their window switches between their bags and bank. They show faded: look, not use. Right-click a character in the list to forget it.",
    Y .. "Where else" .. R .. ": item tooltips get a line like " .. Y .. "Also: Bank 12 · Zyxon 5 · Zyxon bank 20" .. R .. " (turn it off on the Bags page).",
    Y .. "Marks" .. R .. ": a green arrow is gear better than what you wear, a green frame is your next food or water, a big yellow ! is an item that starts a quest you haven't taken yet, a gold border is a quest item, and a yellow !? is an ordinary item one of your quests needs, with how many it still needs under it (it's kept for that).",
    Y .. "Moving items" .. R .. ": pick an item up and hold it over a group: the icons slide apart to open a space under the mouse. Drop it there and it stays at that place in the group (until the bag sorts again: when you open it, or Tidy).",
    Y .. "Armour sets" .. R .. ": items in your equipment sets (the game's equipment manager or ItemRack) get a group of their own at the top, first set first. It only shows while you carry one. Their slots have a red border. They stay where they are: you can use them and put them on (drag one onto your character), but not move them to another group, a box or Hidden, and they're never sold, deleted or disenchanted: Rucksack never sells or throws them away, dropping one outside the bag puts it back, and at a vendor or while a spell waits for an item (Disenchant) a click on one does nothing (at a vendor you can still drag it onto your character). Take an item out of the set in the equipment manager to sell it.",
    Y .. "On the Bags page" .. R .. ": Rows or Packed, columns, size, which groups show. (To use the game's bags again, untick the Bags card in Settings > Modules.)",
    Y .. "Hidden" .. R .. ": the eye in the bags row opens it, a box like the ones beside the bag. Drop an item on its empty slot and the bag stops showing it (it's still in your bags, and usable from there): tools, your Hearthstone, things you never need to look at. Drag an item back onto the bag (a group's +, or the green + in One bag) to see it there again.",
    Y .. "Track bars" .. R .. ": on to start (untick \"Item bar\" on the Bags page to turn them off). The Track button in the bag's tool row opens another one, up to 5; \"Close this bar\" in a bar's menu closes it. A small bar that stays on screen, bag open or not. Pick an item up and drop it on the bar (a green + slot opens where your mouse is, like a group in the bag): it shows how many you carry in all your bags together (80 ore in four stacks shows 80). Click \"Track\" on top for its menu: " .. Y .. "Clickable" .. R .. " (click an item to use it, a fight too) or " .. Y .. "Click-through" .. R .. " (clicks go through it to the world), lock its place, row or column, items you have none of faded or hidden, and remove items. Drag \"Track\" to move it; it keeps its top-left corner, so it grows to the right (or down). Hover an item and click its small red x to take it off (dragging it off the bar or Shift + right-click works too); drag it along the bar to move it. Adding and removing wait until a fight is over.",
    Y .. "Restock" .. R .. ": the cart in the bags row opens a list of the things you always want on you. Pull an item in and type how many to carry. Ticked (the tick on the left): a vendor that sells it tops you up as soon as you open it; with too little money, a bit of each. Unticked: it only stays on the list (never sold or thrown away). Four rows show; a longer list scrolls with the mouse wheel.",
    "It opens and closes with vendors, the mail, the bank, the auction house and trades. At the bank the game's own bank window still opens too.",
  }, "\n") },

  { key = "scrolls", title = "|cff69ccf0Scrolls|r  ·  mages: decipher with one click", text = table.concat({
    "Monsters everywhere drop strange scrolls: " .. Y .. "Scroll:" .. R .. " and then words in capitals, like Scroll: UPDOG. A mage reads them with " .. Y .. "Comprehend Scroll" .. R .. " (from the mage trainer at level 6) and gets a useful scroll out: weapon imbues, familiars, Cryoblast and more. Each one read raises your " .. Y .. "Comprehension" .. R .. " skill.",
    "",
    Y .. "The scroll button" .. R .. ": shows how many scrolls you carry. One click reads the next one (5 seconds, stand still). Shift-drag to move it. The " .. Y .. "Decipher" .. R .. " macro does the same from your bars.",
    Y .. "Which one" .. R .. ": the hardest scroll your skill allows. Each needs some skill (1, 15, 50 or 175, shown on the scroll). Reading one above your skill turns you into a sheep for 8 seconds, so those are skipped until you're good enough.",
    Y .. "In a fight" .. R .. ": the button greys out. Read them somewhere safe.",
    Y .. "Clean-up keeps them" .. R .. ": scrolls sell for coppers, so Clean-up would throw them out first. They're kept (you can untick it). Other classes keep them too, to send to your mage.",
  }, "\n") },

  { key = "haul", title = "|cffd9b36cHaul|r  ·  what your loot is worth", text = table.concat({
    "Haul counts what you loot while you play: the coins, every item and what it's worth, gold per hour, and each " .. Y .. "pull" .. R .. " (a fight and what it dropped). Your runs are kept, day by day.",
    "",
    Y .. "The Haul button" .. R .. " in the bag's tool row (under Rucksack's icon): click opens or closes the Haul window; right-click starts a run, or pauses it. It's gold while a run is on. (Without Rucksack's bag, a coin button on your screen does the same.) /haul works too.",
    Y .. "Start" .. R .. " begins a run: from then on your loot and coins count. " .. Y .. "Pause" .. R .. " stops the clock and the counting until Resume. " .. Y .. "Stop" .. R .. " ends the run and saves it in " .. Y .. "History" .. R .. ".",
    Y .. "What it's worth" .. R .. ": the auction price from the price addons you have (Auctionator, auxForever, AHledger, GoldScout, CraftProfit or Hammerprice; the newest price wins; without one of them Haul only knows vendor prices, and the gold coin doesn't show), and the vendor price. " .. Y .. "Value" .. R .. " at the bottom: best of the two, auction, or vendor. Grey, soulbound and quest items count at the vendor price.",
    Y .. "By value / By pulls" .. R .. " at the bottom: everything together, one line per item, the most valuable first; or each pull with its items, most valuable first.",
    Y .. "Sort loot" .. R .. " (at the bottom of the Haul window): while a run is on, Haul notes which stacks in your bag are your loot, only the pieces you picked up (loot that lands on a stack you had stays stacked there; only the looted part is split off when it goes on Sell). Sort loot then puts what a vendor pays more for on " .. Y .. "Sell" .. R .. " (that stack only: sold at the next vendor, never thrown away); what's worth more at the auction house stays in its own group. Never moved or sold: quest items, food, water and potions, gear better than yours, rare or better, what Rucksack keeps (your professions' materials too), and items with no auction price yet. With " .. Y .. "Sort loot as it comes in" .. R .. " ticked in Settings (on to start), each stack is sorted by itself a second or so after you loot it, while a run is on.",
    Y .. "Stop" .. R .. ": your loot not sorted yet stays noted, so Sort loot still works after it.",
    Y .. "Auction house costs" .. R .. ": posting costs a deposit (from the vendor price: 5 % for 2 hours, 20 % for 8, 60 % for 24; five times that at a neutral house), lost if it doesn't sell, and the house keeps 5 % of the sale (15 % at a neutral house). The deposit comes back when it sells, so Sort loot and the gold coin take only the cut off the auction price; tick \"Count the deposit as lost\" in Haul's Settings to take the deposit off too. Pick your house and length there.",
    Y .. "The gold coin" .. R .. ": an item in your bags with a small gold coin at its top left is worth more at a vendor than what the auction house leaves you. Its tooltip shows the sums. At a vendor, a button under your bag sells all of them (only those stacks). Haul's Check bag button reads the prices afresh and says in chat what's marked. Turn the coin off in Haul's Settings.",
    Y .. "Reset" .. R .. " (bottom of the Haul window): the count starts again from zero; what you had so far goes to History.",
    Y .. "Settings" .. R .. " in the window: which price addons to use, the value, the bag (on or off), the look, and a new session after 2 hours logged out. " .. Y .. "/haul" .. R .. " opens it too.",
  }, "\n") },

  { key = "general", title = "|cffffd100Settings and commands|r", text = table.concat({
    Y .. "Minimap button" .. R .. ": left-click opens Rucksack, right-click shows or hides the Pocket, drag moves it around the minimap.",
    Y .. "Open clams and pouches by itself" .. R .. " (Settings, on unless you switch it off): things that say Right Click to Open and open at once are opened as soon as they're in your bags, one at a time. Clean-up never sells or throws them away while they wait. Not locked boxes, not in a fight, never at a vendor, bank, mailbox, trade or auction house. With full bags it waits for a free slot: Clean-up makes room the usual way, then the rest is opened.",
    Y .. "Tell me when a new version is out" .. R .. " (Settings, on): when you log in, chat says so if a newer Rucksack is out. Rucksack learns it from other players who use it, in your guild and your groups; nobody sees those messages.",
    Y .. "Open Rucksack" .. R .. ": a key that opens and closes the window.",
    Y .. "Modules" .. R .. ": Rucksack comes with all its parts but only loads the ones you pick. Every part is a card you tick or untick. " .. Y .. "Bags" .. R .. " is the bag itself, with selling, deleting and the bank (it starts on); the other cards are extras. Then press Apply (Cancel puts things back). New parts load right away; parts you turned off need a reload, and then they aren't loaded at all. Each character has its own choice, and Scrolls turns itself on for mages only.",
    "",
    Y .. "/ruck" .. R .. " or " .. Y .. "/rucksack" .. R .. ": open the window. Everything else is in here.",
    "",
    G .. "Keys can also be set in the game's Key Bindings, under Rucksack." .. R,
  }, "\n") },
}
